contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(msg.sender != newOwner);
        vm.prank(msg.sender);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        if (ok) {
            assertEq(c.owner(), newOwner);
        } else {
            assertTrue(true);
        }
    }
}

